// The cards of the Insights page. Each card is one claim about how much of Formula 1 results belongs to the driver and how much to the car:
// a headline written from the data (the few facts written by hand are asserted in tests/test-insights.mjs), one chart, and a note on how it was computed and where it can mislead.
// `label` is a short name for the list of slides beside the card (30 characters at most).
// The numbers come from site/js/insights-data.js, generated by packages/research/python/compute-findings.py.
//
// `kind` is how much weight a claim can carry: 'direct' is counted from the results with no rating involved, 'model' uses the ratings
// (and so depends on how they split a team's result between driver and car).
import {
  average,
  drawAxes,
  drawHorizontalBars,
  drawLines,
  drawScatter,
  drawText,
  createSvgElement,
  formatInteger,
  formatOneDecimal,
  formatSigned,
  horizontalBarsHeight,
  interactiveDot,
  legendHtml,
  mountChart,
  surname,
  tableHtml,
} from './insights-charts.js';

const chartIn = (root, name) => root.querySelector(`[data-chart="${name}"]`);

const CIRCUIT_LABELS = [
  ['Marina Bay', 'Singapore'],
  ['Hermanos Rodríguez', 'Mexico City'],
  ['Albert Park', 'Melbourne'],
  ['José Carlos Pace', 'Interlagos'],
  ['Yas Marina', 'Abu Dhabi'],
  ['Sepang', 'Sepang'],
  ['Bahrain', 'Bahrain'],
  ['Villeneuve', 'Montréal'],
  ['Americas', 'Austin'],
  ['Catalunya', 'Barcelona'],
  ['Spa-Francorchamps', 'Spa'],
  ['Enzo e Dino Ferrari', 'Imola'],
  ['Monza', 'Monza'],
  ['Baku', 'Baku'],
  ['Shanghai', 'Shanghai'],
  ['Monaco', 'Monaco'],
];
const circuitLabel = (name) => (CIRCUIT_LABELS.find(([fragment]) => name.includes(fragment)) || [null, name.replace(' Circuit', '')])[1];
export const INSIGHT_TOPICS = [
  { id: 'extremes', title: 'Rating extremes' },
  { id: 'drivers', title: 'Drivers and championships' },
  { id: 'racing', title: 'Cars and racing' },
];

function ratingExtremeCard({ id, title, label, key, entity, highest }) {
  return {
    id,
    topic: 'extremes',
    kind: 'model',
    title,
    label,
    lead: (data) => {
      const first = data.ratingExtremes[key][0];
      return `${first.name} is ${highest ? 'highest' : 'lowest'}, at ${formatInteger(first.rating)} after the ${first.year} ${first.grandPrix}.`;
    },
    body: () => '<div class="insight-chart" data-chart="main"></div><div class="insight-extra" data-chart="details"></div>',
    how: (data) =>
      `The ${highest ? 'highest' : 'lowest'} displayed overall ${entity} rating reached after a rated Grand Prix, with each ${entity === 'driver' ? 'driver' : 'team'} appearing once. These are the same retrospective ratings and 20-weekend display reference as Ratings and History, including the filtered latest weekend. Data starts in ${data.equalCarTitles.seasons[0].year}; even short careers and partial seasons are included. Historical estimates can change as new races are added. Early ratings depend on the starting assumptions, and cross-era comparisons are uncertain.`,
    draw: (data, root) => {
      const rows = data.ratingExtremes[key];
      const items = rows.map((row) => ({
        label: `${row.year} ${entity === 'driver' ? surname(row.name) : row.name}`,
        bars: [
          {
            value: row.rating,
            color: highest ? 'var(--s2)' : 'var(--s1)',
            name: `rating after ${row.grandPrix}`,
            text: '',
          },
        ],
      }));
      const minimum = Math.min(1000, ...rows.map((row) => row.rating));
      const maximum = Math.max(1000, ...rows.map((row) => row.rating));
      const padding = Math.max(5, (maximum - minimum) * 0.1);
      mountChart(
        chartIn(root, 'main'),
        (svg, width) => {
          drawHorizontalBars(svg, width, items, {
            marginLeft: Math.min(150, width * 0.42),
            marginRight: 38,
            rowHeight: 24,
            baseline: 1000,
            minimum: minimum < 1000 ? minimum - padding : 1000,
            maximum: maximum > 1000 ? maximum + padding : 1000,
            ticks: [1000],
          });
          rows.forEach((row, index) =>
            drawText(svg, width - 33, 18 + index * 24, formatInteger(row.rating), {
              baseline: 'middle',
              className: 'rating-extreme-value',
            }),
          );
        },
        () => horizontalBarsHeight(items.length, 24),
      );
      chartIn(root, 'details').innerHTML = tableHtml(
        [entity === 'driver' ? 'Driver' : 'Car', 'Grand Prix', 'Rating'],
        rows.map((row) => [row.name, `${row.year} ${row.grandPrix}`, formatInteger(row.rating)]),
        [2],
      );
    },
  };
}

export const INSIGHT_CARDS = [
  ratingExtremeCard({
    id: 'driver-peak-ratings',
    title: 'The highest driver ratings',
    label: 'Highest driver ratings',
    key: 'driverHigh',
    entity: 'driver',
    highest: true,
  }),
  ratingExtremeCard({
    id: 'driver-low-ratings',
    title: 'The lowest driver ratings',
    label: 'Lowest driver ratings',
    key: 'driverLow',
    entity: 'driver',
    highest: false,
  }),
  ratingExtremeCard({
    id: 'car-peak-ratings',
    title: 'The highest car ratings',
    label: 'Highest car ratings',
    key: 'carHigh',
    entity: 'car',
    highest: true,
  }),
  ratingExtremeCard({
    id: 'car-low-ratings',
    title: 'The lowest car ratings',
    label: 'Lowest car ratings',
    key: 'carLow',
    entity: 'car',
    highest: false,
  }),
  {
    id: 'explained-share',
    topic: 'racing',
    kind: 'model',
    title: 'How much of a race result is the car?',
    label: 'How much is the car',
    lead: (data) => {
      const car = average(data.explainedShare.map((row) => row.car)) * 100;
      const driver = average(data.explainedShare.map((row) => row.driver)) * 100;
      const between = average(data.explainedShare.filter((row) => row.year < data.dataThrough.year).map((row) => row.betweenTeams)) * 100;
      const first = data.explainedShare[0].year;
      const last = data.explainedShare.at(-1).year;
      return `Over ${first} to ${last} the car accounts for about ${formatInteger(car)}% of what the ratings explain in race-by-race comparisons, the driver about ${formatInteger(driver)}%. Looking only at season-average results, about ${formatInteger(between)}% of the differences between drivers sit between teams.`;
    },
    body: () =>
      legendHtml([
        ['var(--s1)', 'Car share of explained results'],
        ['var(--s2)', 'Driver share'],
        ['var(--ink)', 'Between-team share of season-average results (no model)'],
      ]) + '<div class="insight-chart" data-chart="main"></div>',
    how: () =>
      "<b>Bars:</b> for every pair of drivers in a race, the pre-race car and driver rating gaps predict who finishes ahead. The explained signal is split between the two by averaging each one's contribution with and without the other (a Shapley split; Shapley 1953, Lipovetsky and Conklin 2001), in 3-season windows, with the signal measured by the pseudo-R² of logistic fits (McFadden 1974). <b>Dots:</b> the intraclass correlation (Shrout and Fleiss 1979) of each driver's average finishing percentile within a season, which needs no ratings. The two views measure different things (single races against a season), so read the dots as an independent check on the direction, not on the exact share.",
    draw: (data, root) => {
      const rows = data.explainedShare;
      mountChart(
        chartIn(root, 'main'),
        (svg, width, height) => {
          const axes = drawAxes(svg, width, height, {
            xDomain: [rows[0].year - 0.6, rows.at(-1).year + 0.6],
            yDomain: [0, 1],
            xTicks: [2000, 2005, 2010, 2015, 2020, 2025],
            yTicks: [0, 0.25, 0.5, 0.75, 1],
            yFormat: (value) => `${value * 100}%`,
          });
          const barWidth = (axes.x(2004) - axes.x(2003)) * 0.72;
          for (const row of rows) {
            svg.append(
              createSvgElement(
                'rect',
                {
                  x: axes.x(row.year) - barWidth / 2,
                  y: axes.y(row.car),
                  width: barWidth,
                  height: axes.y(0) - axes.y(row.car),
                  fill: 'var(--s1)',
                },
                [createSvgElement('title', {}, `${row.year}: car ${formatInteger(row.car * 100)}%`)],
              ),
            );
            svg.append(
              createSvgElement(
                'rect',
                {
                  x: axes.x(row.year) - barWidth / 2,
                  y: axes.y(1),
                  width: barWidth,
                  height: axes.y(row.car) - axes.y(1) - 1.5,
                  fill: 'var(--s2)',
                },
                [createSvgElement('title', {}, `${row.year}: driver ${formatInteger(row.driver * 100)}%`)],
              ),
            );
          }
          svg.append(
            createSvgElement('polyline', {
              points: rows.map((row) => `${axes.x(row.year)},${axes.y(row.betweenTeams)}`).join(' '),
              fill: 'none',
              stroke: 'var(--ink)',
              'stroke-width': 1.5,
            }),
          );
          for (const row of rows) {
            svg.append(
              interactiveDot(
                svg,
                createSvgElement('circle', {
                  cx: axes.x(row.year),
                  cy: axes.y(row.betweenTeams),
                  r: 4,
                  fill: 'var(--ink)',
                  stroke: 'var(--surface)',
                }),
                `${row.year}: between teams ${formatInteger(row.betweenTeams * 100)}%`,
              ),
            );
          }
        },
        () => 290,
      );
    },
  },
  {
    id: 'circuit-weights',
    topic: 'racing',
    kind: 'model',
    title: 'How much do driver and car ratings predict at each circuit?',
    label: 'Driver and car by circuit',
    lead: (data) => {
      const rows = [...data.circuitWeights].sort((a, b) => b.driverWeight - b.carWeight - (a.driverWeight - a.carWeight));
      const driver = rows[0];
      const car = rows.at(-1);
      return `${circuitLabel(driver.name)} has the largest driver-versus-car weight difference (${driver.driverWeight} versus ${driver.carWeight}); ${circuitLabel(car.name)} has the largest car-versus-driver difference (${car.carWeight} versus ${car.driverWeight}). These estimates are uncertain.`;
    },
    body: () => '<div class="insight-chart" data-chart="main"></div>',
    how: () =>
      'Per circuit with at least 10 races, a logistic regression (Cox 1958) of "who finishes ahead" on the pre-race driver gap and car gap (cross-team pairs). A weight of 1 means the ratings predict that circuit exactly as well as elsewhere; 0.5 means results there depend half as much on that factor. With about 20 races per circuit the error bars are wide, so treat positions as a tendency, not a ranking.',
    draw: (data, root) => {
      const points = data.circuitWeights.map((row) => {
        const driverShare = row.driverWeight / (row.driverWeight + row.carWeight);
        return {
          x: row.carWeight,
          y: row.driverWeight,
          label: circuitLabel(row.name),
          tooltip: `${row.name}: car ${row.carWeight}, driver ${row.driverWeight} (${row.races} races)`,
          color: driverShare > 0.55 ? 'var(--s2)' : driverShare < 0.45 ? 'var(--s1)' : 'var(--ink-3)',
          priority: Math.abs(row.driverWeight - row.carWeight),
        };
      });
      mountChart(
        chartIn(root, 'main'),
        (svg, width, height) =>
          drawScatter(svg, width, height, {
            xDomain: [0.5, 1.4],
            yDomain: [0.3, 1.3],
            xTicks: [0.6, 0.8, 1, 1.2, 1.4],
            yTicks: [0.4, 0.6, 0.8, 1, 1.2],
            xFormat: (value) => value.toFixed(1),
            yFormat: (value) => value.toFixed(1),
            xTitle: 'weight on the car gap (1 = ratings are right)',
            yTitle: 'weight on the driver gap',
            guides: [[0.5, 0.5, 1.3, 1.3]],
            radius: 5,
            points,
          }),
        (width) => Math.max(340, Math.min(470, width * 0.72)),
      );
    },
  },
  {
    id: 'champions',
    topic: 'drivers',
    kind: 'model',
    title: 'Every champion, split into driver and car',
    label: 'Every champion split',
    lead: (data) => {
      const champions = data.champions.map((row) => ({ ...row, driverShare: row.driverRating / (row.driverRating + row.carRating) }));
      const mostDriver = champions.reduce((best, row) => (row.driverShare > best.driverShare ? row : best));
      const mostCar = champions.reduce((best, row) => (row.driverShare < best.driverShare ? row : best));
      return `Champions ride a car that is at least ${formatInteger(Math.min(...champions.map((row) => row.carRating)))} points above average. The most driver-made title is ${mostDriver.name} ${mostDriver.year}; the most car-made is ${mostCar.name} ${mostCar.year}.`;
    },
    body: () =>
      legendHtml([
        ['var(--s2)', 'Driver (portable rating)'],
        ['var(--s1)', 'Car'],
        ['var(--ink)', 'Total package'],
      ]) + '<div class="insight-chart" data-chart="main"></div>',
    how: () =>
      'Season-average ratings relative to the field for the points leader of each season (sprint points not counted). Package = driver + car, in rating points. Negative driver values would extend left of zero.',
    draw: (data, root) => {
      const items = data.champions.map((row) => ({
        label: `${row.year}  ${surname(row.name)}`,
        segments: [
          { value: row.driverRating, color: 'var(--s2)', name: 'driver' },
          { value: row.carRating, color: 'var(--s1)', name: 'car' },
        ],
        total: row.driverRating + row.carRating,
      }));
      const minimum = Math.min(-5, ...items.map((item) => item.segments.reduce((sum, segment) => sum + Math.min(0, segment.value), 0) - 5));
      const maximum = Math.max(...items.map((item) => item.segments.reduce((sum, segment) => sum + Math.max(0, segment.value), 0))) + 5;
      const ticks = Array.from({ length: Math.floor(maximum / 50) + 1 }, (_, index) => index * 50);
      mountChart(
        chartIn(root, 'main'),
        (svg, width) => drawHorizontalBars(svg, width, items, { marginLeft: 110, ticks, minimum, maximum, rowHeight: 19 }),
        () => horizontalBarsHeight(items.length, 19),
      );
    },
  },
  {
    id: 'equal-car-titles',
    topic: 'drivers',
    kind: 'model',
    title: 'How might title chances change in another era?',
    label: 'Title chances across eras',
    lead: (data) => {
      const first = data.eraTiming[0];
      return `${first.name} won ${first.actualTitles} titles in the rated period. With equal cars, the model estimates ${first.actualEra.toFixed(2)} in those years and a median of ${first.median.toFixed(2)} across ${first.alternatives} other career placements.`;
    },
    body: () =>
      '<div class="insight-grid"><div><h4>Equal cars in their own years</h4><div data-chart="actual-years"></div></div><div><h4>Equal cars in other eras</h4><div data-chart="other-eras"></div></div></div><div class="insight-extra" data-chart="details"></div><div class="insight-extra" data-chart="seasons"></div>',
    how: (data) => {
      const seasons = data.equalCarTitles.seasons;
      return `Each point is a driver: the horizontal axis is actual titles, and the vertical axis is the expected number with equal cars. The first chart uses the driver’s own years; the second uses the median across other career placements. The dashed line marks equal actual and expected totals. Hover, focus or tap a point for the driver and values; the table lists all drivers. Each driver's eligible career seasons from ${seasons[0].year}–${seasons.at(-1).year} are moved as a sequence through every other placement that fits in those completed years, preserving gaps. For each season, we estimate the chance of having the highest season-average portable driver rating against that year's field in equal cars; these chances add to expected titles. The table shows the minimum and maximum across alternative placements. Drivers need at least three eligible seasons, at least one alternative placement, and either an actual title or at least 0.25 expected titles in some alternative. A season is eligible after at least eight races and half its rounds. Careers and titles before ${seasons[0].year} and the incomplete current season are excluded; long careers have fewer possible placements. A driver's own historical entry is removed from each comparison field. Ratings are relative to their original grids and eras are not perfectly comparable; the estimate does not simulate championships or how rivals might change. Rating uncertainty is an approximate marginal from the unified posterior; these exploratory draws treat drivers independently, and early seasons have less rating history and incomplete qualifying records. Differences from actual titles also reflect real cars and other factors, so they do not prove luck. The second table lists seasons where the likeliest best driver was not the champion, using 6,000 draws of approximate rating uncertainty.`;
    },
    draw: (data, root) => {
      const rows = data.eraTiming;
      const maximum = Math.max(2, Math.ceil(Math.max(...rows.flatMap((row) => [row.actualTitles, row.actualEra, row.median])) / 2) * 2);
      for (const [chart, field, description, color] of [
        ['actual-years', 'actualEra', 'their own years', 'var(--s2)'],
        ['other-eras', 'median', 'median in other eras', 'var(--s3)'],
      ]) {
        const points = rows.map((row) => ({
          x: row.actualTitles,
          y: row[field],
          label: surname(row.name),
          tooltip: `${row.name}: ${row.actualTitles} actual titles; ${row[field].toFixed(2)} expected titles with equal cars (${description})`,
          priority: Math.abs(row[field] - row.actualTitles),
          color,
        }));
        mountChart(
          chartIn(root, chart),
          (svg, width, height) =>
            drawScatter(svg, width, height, {
              xDomain: [-0.5, maximum + 0.5],
              yDomain: [-0.5, maximum + 0.5],
              xTicks: Array.from({ length: maximum / 2 + 1 }, (_, index) => index * 2),
              yTicks: Array.from({ length: maximum / 2 + 1 }, (_, index) => index * 2),
              xTitle: 'actual titles',
              yTitle: 'expected titles in equal cars',
              guides: [[0, 0, maximum, maximum]],
              points,
            }),
          (width) => Math.max(260, Math.min(360, width * 0.8)),
        );
      }
      chartIn(root, 'details').innerHTML =
        '<h4>Career comparison</h4>' +
        tableHtml(
          ['Driver', 'Actual titles', 'Equal cars: actual years', 'Other eras: median', 'Other eras: range'],
          rows.map((row) => [
            row.name,
            row.actualTitles,
            row.actualEra.toFixed(2),
            row.median.toFixed(2),
            `${row.minimum.toFixed(2)}–${row.maximum.toFixed(2)}`,
          ]),
          [1, 2, 3, 4],
        );
      const differing = data.equalCarTitles.seasons.filter((row) => row.likeliestBest !== row.champion);
      chartIn(root, 'seasons').innerHTML =
        '<h4>Seasons where the likeliest best driver was not the champion</h4>' +
        tableHtml(
          ['Season', 'Likeliest best driver', 'Chance', 'Champion'],
          differing.map((row) => [row.year, row.likeliestBest, `${formatInteger(row.probability * 100)}%`, row.champion]),
          [2],
        );
    },
  },
  {
    id: 'career-driver-and-car',
    topic: 'drivers',
    kind: 'model',
    title: 'Carried or carrying: career car against career driver',
    label: 'Carried or carrying',
    lead: (data) => {
      const hamilton = data.careerDriverAndCar.find((row) => row.name === 'Lewis Hamilton');
      const alonso = data.careerDriverAndCar.find((row) => row.name === 'Fernando Alonso');
      return `Hamilton's average car rating was ${formatInteger(hamilton.carRating)} points above the field. Alonso's average car was ${formatInteger(alonso.carRating)} points above it, with a driver rating of ${formatInteger(alonso.driverRating)}.`;
    },
    body: () => '<div class="insight-chart" data-chart="main"></div>',
    how: () =>
      "Average portable driver rating and average car rating over all of a driver's starts since 1994 (drivers with at least 60). Top right: strong drivers in strong cars. Top left: strong drivers in weak cars. Bottom right: strong cars, ordinary drivers. Only some names are labelled; hover, focus or tap a dot for the rest.",
    draw: (data, root) => {
      const points = data.careerDriverAndCar.map((row) => ({
        x: row.carRating,
        y: row.driverRating,
        label: surname(row.name),
        tooltip: `${row.name}: car ${formatInteger(row.carRating)}, driver ${formatInteger(row.driverRating)}, ${row.starts} starts`,
        priority: Math.abs(row.driverRating) + Math.abs(row.carRating) / 2,
        radius: 3 + Math.min(5, row.starts / 120),
      }));
      const bounds = (values, minimum, maximum) => {
        const lower = Math.floor(Math.min(minimum, ...values) / 20) * 20;
        const upper = Math.ceil(Math.max(maximum, ...values) / 20) * 20;
        return {
          domain: [lower - 5, upper + 5],
          ticks: Array.from({ length: (upper - lower) / 20 + 1 }, (_, index) => lower + index * 20),
        };
      };
      const cars = bounds(
        points.map((point) => point.x),
        -80,
        80,
      );
      const drivers = bounds(
        points.map((point) => point.y),
        -40,
        40,
      );
      mountChart(
        chartIn(root, 'main'),
        (svg, width, height) => {
          const axes = drawScatter(svg, width, height, {
            xDomain: cars.domain,
            yDomain: drivers.domain,
            xTicks: cars.ticks,
            yTicks: drivers.ticks,
            xTitle: 'average car rating (points above the field)',
            yTitle: 'average driver rating',
            points,
          });
          svg.insertBefore(
            createSvgElement('line', { x1: axes.x(0), x2: axes.x(0), y1: axes.top, y2: height - axes.bottom, class: 'zero' }),
            svg.firstChild.nextSibling,
          );
        },
        (width) => Math.max(330, Math.min(480, width * 0.7)),
      );
    },
  },
  {
    id: 'teammate-gaps',
    topic: 'drivers',
    kind: 'model',
    title: 'How large are teammate rating gaps?',
    label: 'Teammate rating gaps',
    lead: (data) => {
      const largest = data.teammates.largestGaps[0];
      const redBull = data.teammates.teamAverages.at(-1);
      const odds = formatInteger(10 ** (largest.gap / 75));
      return `The largest teammate gap since 1994 is ${largest.ahead} over ${largest.behind} in ${largest.year}: ${formatInteger(largest.gap)} rating points, about ${odds}-to-1 odds in a duel. ${redBull.team}'s two cars are the most lopsided pairing of any team (average gap ${formatInteger(redBull.gap)} points).`;
    },
    body: () =>
      '<div class="insight-grid"><div><h4>Largest teammate gaps (season)</h4><div data-chart="largest"></div></div><div><h4>Verstappen against his teammate, by season</h4><div data-chart="verstappen"></div></div><div><h4>Career average gap to teammates (80+ races together)</h4><div data-chart="career"></div></div><div><h4>Average teammate gap by team (6+ pairings)</h4><div data-chart="teams"></div></div></div>',
    how: () =>
      'For each pair of teammates with at least 8 races together in a season, the average difference of their published ratings. Teammates share the car, so this is the best-identified number in the model. Career figure: gaps weighted by races together.',
    draw: (data, root) => {
      const { largestGaps, verstappen, careerGaps, teamAverages } = data.teammates;
      const bars = (rows, labelOf, colorOf) =>
        rows.map((row) => ({ label: labelOf(row), bars: [{ value: row.gap, color: colorOf(row), name: 'gap' }] }));
      const draw = (name, items, options) =>
        mountChart(
          chartIn(root, name),
          (svg, width) => drawHorizontalBars(svg, width, items, { format: formatInteger, ...options }),
          () => horizontalBarsHeight(items.length, options.rowHeight),
        );
      draw(
        'largest',
        bars(
          largestGaps,
          (row) => `${row.year} ${surname(row.ahead)} > ${surname(row.behind)}`,
          () => 'var(--s2)',
        ),
        {
          marginLeft: 158,
          rowHeight: 22,
          minimum: 0,
          maximum: 130,
        },
      );
      draw(
        'verstappen',
        bars(
          verstappen,
          (row) => `${row.year} ${surname(row.teammate)}`,
          (row) => (row.gap >= 0 ? 'var(--s2)' : 'var(--s1)'),
        ),
        {
          marginLeft: 110,
          rowHeight: 19,
          minimum: -30,
          maximum: 130,
          ticks: [0],
        },
      );
      const career = [...careerGaps.slice(0, 8), ...careerGaps.slice(-6)];
      draw(
        'career',
        bars(
          career,
          (row) => row.name,
          (row) => (row.gap >= 0 ? 'var(--s3)' : 'var(--s5)'),
        ),
        {
          marginLeft: 130,
          rowHeight: 19,
          minimum: -62,
          maximum: 62,
          ticks: [0],
        },
      );
      draw(
        'teams',
        bars(
          [...teamAverages].reverse(),
          (row) => row.team,
          () => 'var(--s4)',
        ),
        { marginLeft: 100, rowHeight: 19, minimum: 0, maximum: 48 },
      );
    },
  },
  {
    id: 'qualifying-versus-race',
    topic: 'drivers',
    kind: 'model',
    title: 'Saturday drivers and Sunday drivers',
    label: 'Saturday and Sunday',
    lead: (data) => {
      const drivers = data.qualifyingVersusRace.drivers;
      const saturday = [...drivers]
        .sort((a, b) => b.difference - a.difference)
        .slice(0, 3)
        .map((row) => surname(row.name));
      const sunday = [...drivers]
        .sort((a, b) => a.difference - b.difference)
        .slice(0, 4)
        .map((row) => surname(row.name));
      const car = data.qualifyingVersusRace.cars.reduce((best, row) => (row.difference > best.difference ? row : best));
      return `Some drivers have higher qualifying than race ratings (${saturday.join(', ')}) and some the reverse (${sunday.join(', ')}). A driver's even-numbered seasons predict their odd-numbered ones with a correlation of ${data.qualifyingVersusRace.splitHalfCorrelation}. For cars, ${car.team} ${car.year} has the largest qualifying-to-race difference in this comparison (+${formatOneDecimal(car.difference)} points).`;
    },
    body: () =>
      legendHtml([
        ['var(--s2)', 'Better in qualifying than in the race'],
        ['var(--s1)', 'Better in the race than in qualifying'],
      ]) +
      '<div class="insight-grid"><div><h4>Drivers: qualifying rating minus race rating (4+ seasons)</h4><div data-chart="drivers"></div></div><div><h4>Cars: the five biggest gaps each way (team-seasons)</h4><div data-chart="cars"></div></div></div>',
    how: () =>
      "Per season, the driver's qualifying rating minus race rating (both relative to the field and measured on the same timing scale; partial pooling can shrink their differences), averaged over seasons, with one standard error. Cars: the same difference per team and season.",
    draw: (data, root) => {
      const drivers = data.qualifyingVersusRace.drivers.map((row) => ({
        label: row.name,
        bars: [
          {
            value: row.difference,
            error: row.standardError,
            color: row.difference >= 0 ? 'var(--s2)' : 'var(--s1)',
            name: 'qualifying − race',
            text: formatSigned(row.difference),
          },
        ],
      }));
      mountChart(
        chartIn(root, 'drivers'),
        (svg, width) =>
          drawHorizontalBars(svg, width, drivers, {
            marginLeft: 130,
            rowHeight: 21,
            minimum: -24,
            maximum: 26,
            ticks: [-20, 0, 20],
            format: formatInteger,
          }),
        () => horizontalBarsHeight(drivers.length, 21),
      );
      const cars = data.qualifyingVersusRace.cars
        .map((row) => ({
          label: `${row.team} ${row.year}`,
          bars: [
            {
              value: row.difference,
              color: row.difference >= 0 ? 'var(--s2)' : 'var(--s1)',
              name: 'qualifying − race',
              text: formatSigned(row.difference),
            },
          ],
        }))
        .reverse();
      mountChart(
        chartIn(root, 'cars'),
        (svg, width) =>
          drawHorizontalBars(svg, width, cars, {
            marginLeft: 138,
            rowHeight: 21,
            minimum: -85,
            maximum: 62,
            ticks: [-60, -30, 0, 30, 60],
            format: formatInteger,
          }),
        () => horizontalBarsHeight(cars.length, 21),
      );
    },
  },
  {
    id: 'ageing',
    topic: 'drivers',
    kind: 'model',
    title: 'The ageing curve, and the careers behind it',
    label: 'The ageing curve',
    lead: (data) => {
      const career = data.ageing.careers['Michael Schumacher'];
      const ferrari = career.filter((season) => season.year >= 1996 && season.year <= 2006);
      const comeback = career.filter((season) => season.year >= 2010);
      const earlyThirties = data.ageing.yearlyChange.filter((row) => row.age >= 30 && row.age <= 33);
      const earlyTwenties = data.ageing.yearlyChange.filter((row) => row.age >= 20 && row.age <= 24);
      const lateTwenties = data.ageing.yearlyChange.filter((row) => row.age >= 25 && row.age <= 29);
      return `Average annual rating change is ${formatSigned(average(earlyTwenties.map((row) => row.mean)))} points from ages 20 to 24 and ${formatSigned(average(lateTwenties.map((row) => row.mean)))} from 25 to 29. From ages 30 to 33, the average annual change is ${formatSigned(average(earlyThirties.map((row) => row.mean)))} rating points. Schumacher's comeback at 41 to 43 averaged ${formatInteger(average(comeback.map((season) => season.rating)))} points above the field, compared with ${formatInteger(average(ferrari.map((season) => season.rating)))} in his Ferrari years.`;
    },
    body: () =>
      legendHtml([
        ['var(--s7)', 'Schumacher'],
        ['var(--s3)', 'Alonso'],
        ['var(--s1)', 'Hamilton'],
        ['var(--s2)', 'Verstappen'],
        ['var(--s5)', 'Vettel'],
        ['var(--s4)', 'Räikkönen'],
      ]) +
      '<div class="insight-grid"><div><h4>Average change in rating from one season to the next, by age at the first race</h4><div data-chart="steps"></div></div><div><h4>Season rating by age at the first race</h4><div data-chart="careers"></div></div></div>',
    how: () =>
      'Age is the driver’s completed years on their first rated Grand Prix date of that season, calculated from their birth date. Left: for drivers with consecutive full seasons (8+ races each), the mean change in portable rating by starting age, with one standard error; ages with fewer than 8 cases are dropped. Survivor bias applies: drivers who decline sharply leave, so late-career declines are understated. Right: season-average portable rating by starting age.',
    draw: (data, root) => {
      mountChart(
        chartIn(root, 'steps'),
        (svg, width, height) => {
          const axes = drawAxes(svg, width, height, {
            xDomain: [20, 39],
            yDomain: [-12, 22],
            xTicks: [20, 24, 28, 32, 36],
            yTicks: [-10, 0, 10, 20],
            xTitle: 'age',
          });
          for (const step of data.ageing.yearlyChange) {
            svg.append(
              createSvgElement('line', {
                x1: axes.x(step.age),
                x2: axes.x(step.age),
                y1: axes.y(step.mean - step.standardError),
                y2: axes.y(step.mean + step.standardError),
                stroke: 'var(--ink-3)',
              }),
            );
            svg.append(
              interactiveDot(
                svg,
                createSvgElement('circle', {
                  cx: axes.x(step.age),
                  cy: axes.y(step.mean),
                  r: 4,
                  fill: step.mean >= 0 ? 'var(--s3)' : 'var(--s5)',
                  stroke: 'var(--surface)',
                }),
                `age ${step.age}: ${formatOneDecimal(step.mean)} ± ${formatOneDecimal(step.standardError)} (${step.cases} cases)`,
              ),
            );
          }
        },
        () => 270,
      );
      const colors = {
        'Michael Schumacher': 'var(--s7)',
        'Fernando Alonso': 'var(--s3)',
        'Lewis Hamilton': 'var(--s1)',
        'Max Verstappen': 'var(--s2)',
        'Sebastian Vettel': 'var(--s5)',
        'Kimi Räikkönen': 'var(--s4)',
      };
      const careerRatings = Object.values(data.ageing.careers).flatMap((seasons) => seasons.map((season) => season.rating));
      const ratingLowerBound = Math.floor(Math.min(-10, ...careerRatings) / 25) * 25;
      const ratingUpperBound = Math.ceil(Math.max(90, ...careerRatings) / 25) * 25;
      mountChart(
        chartIn(root, 'careers'),
        (svg, width, height) =>
          drawLines(svg, width, height, {
            xDomain: [18, 46],
            yDomain: [ratingLowerBound, ratingUpperBound],
            xTicks: [20, 25, 30, 35, 40, 45],
            yTicks: Array.from({ length: (ratingUpperBound - ratingLowerBound) / 25 + 1 }, (_, index) => ratingLowerBound + index * 25),
            xTitle: 'age',
            series: Object.entries(data.ageing.careers).map(([name, seasons]) => ({
              name,
              color: colors[name],
              points: seasons.map((season) => [season.age, season.rating]),
              markers: true,
              width: 1.6,
            })),
          }),
        () => 270,
      );
    },
  },
  {
    id: 'upsets',
    topic: 'racing',
    kind: 'model',
    title: 'The biggest upsets: winners the ratings gave no chance',
    label: 'The biggest upsets',
    lead: (data) => {
      const [first, ...rest] = data.upsets;
      const followers = rest.slice(0, 3).map((row) => `${row.driver} (${row.year} ${row.grandPrix}, 1 in ${row.oddsAgainst})`);
      return `${first.driver}'s ${first.year} ${first.grandPrix} win for ${first.team} was a 1-in-${first.oddsAgainst} event on pre-race ratings. ${followers.join(', ')} follow.`;
    },
    body: () => '<div class="insight-chart" data-chart="main"></div>',
    how: () =>
      "Before each race, each entry's strength is its driver plus car overall strength rating from the previous weekend; win probability is the logistic (softmax) share across the field (Plackett 1975). It ignores retirements, which makes favourites look a little stronger than they were, and is an exploratory ranking calculation, not the site’s calibrated head-to-head forecast or a validated winner probability.",
    draw: (data, root) => {
      const items = data.upsets.map((row) => ({
        label: `${row.year} ${row.grandPrix}, ${surname(row.driver)}`,
        bars: [{ value: Math.log10(row.oddsAgainst), color: 'var(--s2)', name: '1 in', text: `1 in ${row.oddsAgainst}` }],
      }));
      mountChart(
        chartIn(root, 'main'),
        (svg, width) =>
          drawHorizontalBars(svg, width, items, {
            marginLeft: Math.min(250, width * 0.62),
            marginRight: 60,
            rowHeight: 24,
            minimum: 0,
            maximum: 2.5,
          }),
        () => horizontalBarsHeight(items.length, 24) - 10,
      );
    },
  },
];
